SELECT property_code, dashboard_id, id, name FROM properties WHERE UPPER(property_code) IN ('AZR', 'VCB', 'VCKB') ORDER BY property_code;
UPDATE dashboard_bookings SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'AZR'), property_code = 'AZR', property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'AZR') WHERE UPPER(property_code) = 'AZA' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'AZR');
UPDATE dashboard_bookings SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'VCB'), property_code = 'VCB', property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'VCB') WHERE UPPER(property_code) = 'CSB' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'VCB');
UPDATE dashboard_bookings SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'VCKB'), property_code = 'VCKB', property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'VCKB') WHERE UPPER(property_code) = 'CKB' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'VCKB');
UPDATE finance_entries SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'AZR'), property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'AZR') WHERE (UPPER(property_id) = 'BELUM-AZA' OR property_id IN (SELECT id FROM properties WHERE UPPER(property_code) = 'AZA') OR property_id IN (SELECT dashboard_id FROM properties WHERE UPPER(property_code) = 'AZA')) AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'AZR');
UPDATE finance_entries SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'VCB'), property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'VCB') WHERE (UPPER(property_id) = 'BELUM-CSB' OR property_id IN (SELECT id FROM properties WHERE UPPER(property_code) = 'CSB') OR property_id IN (SELECT dashboard_id FROM properties WHERE UPPER(property_code) = 'CSB')) AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'VCB');
UPDATE finance_entries SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'VCKB'), property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'VCKB') WHERE (UPPER(property_id) = 'BELUM-CKB' OR property_id IN (SELECT id FROM properties WHERE UPPER(property_code) = 'CKB') OR property_id IN (SELECT dashboard_id FROM properties WHERE UPPER(property_code) = 'CKB')) AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'VCKB');
UPDATE dashboard_management_data SET data_json = json_set(data_json, '$.properties', COALESCE((SELECT json_group_array(json(value)) FROM json_each(dashboard_management_data.data_json, '$.properties') WHERE UPPER(COALESCE(json_extract(value, '$.code'), '')) NOT IN ('AZA', 'CSB', 'CKB')), json('[]'))) WHERE id = 'main';
DELETE FROM properties WHERE UPPER(property_code) = 'AZA' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'AZR');
DELETE FROM properties WHERE UPPER(property_code) = 'CSB' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'VCB');
DELETE FROM properties WHERE UPPER(property_code) = 'CKB' AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'VCKB');
SELECT (SELECT COUNT(*) FROM properties WHERE UPPER(property_code) IN ('AZA', 'CSB', 'CKB')) AS sisa_properti, (SELECT COUNT(*) FROM dashboard_bookings WHERE UPPER(property_code) IN ('AZA', 'CSB', 'CKB')) AS sisa_booking, (SELECT COUNT(*) FROM properties WHERE UPPER(property_code) = 'AZR') AS ada_AZR, (SELECT COUNT(*) FROM properties WHERE UPPER(property_code) = 'VCB') AS ada_VCB, (SELECT COUNT(*) FROM properties WHERE UPPER(property_code) = 'VCKB') AS ada_VCKB;
